'use strict';
const canvas=document.getElementById('game'),ctx=canvas.getContext('2d');
const hint=document.getElementById('hint'),statusEl=document.getElementById('status'),pauseButton=document.getElementById('pause');
let best=0;try{best=Number(localStorage.getItem('dino-best'))||0}catch{}
let state='ready',score=0,speed=6,tick=0,ground=0,next=90,obstacles=[],clouds=[{x:170,y:44},{x:440,y:65},{x:610,y:24}],last=0,deadAt=0;
const dino={x:42,y:0,vy:0,duck:false};
const standing=['00000000111111111100','00000001111111111110','00000001101111111110','00000001111111111110','00000001111111111110','00000001111100000000','00000001111111100000','10000011111000000000','10000111111000000000','11001111111110000000','11111111111010000000','11111111111000000000','01111111110000000000','00111111110000000000','00011111100000000000','00001101100000000000','00001100110000000000','00001100010000000000','00001110011000000000'];
function rect(x,y,w,h){ctx.fillRect(Math.round(x),Math.round(y),w,h)}
function drawDino(){const y=166-dino.y;if(dino.duck&&dino.y===0){rect(42,y-21,36,15);rect(74,y-25,25,15);ctx.clearRect(79,y-22,3,3);rect(38,y-25,5,12);rect(51,y-7,5,7);rect(77,y-7,5,7)}else{standing.forEach((r,j)=>[...r].forEach((p,i)=>{if(p==='1')rect(dino.x+i*2,y-38+j*2,2,2)}));if(state==='running'&&dino.y===0){ctx.clearRect(tick%16<8?50:60,y-6,8,6);rect(tick%16<8?50:60,y-9,8,3)}if(state==='dead'){rect(58,y-34,6,2);rect(60,y-36,2,6)}}}
function cactus(o){for(let n=0;n<o.count;n++){let x=o.x+n*17,y=166,h=o.h;rect(x+6,y-h,6,h);rect(x,y-h+9,4,15);rect(x+3,y-h+21,6,4);rect(x+14,y-h+5,4,16);rect(x+10,y-h+17,7,4)}}
function bird(o){rect(o.x+10,o.y+7,23,8);rect(o.x,o.y+7,13,3);rect(o.x+8,o.y,9,13);let flap=tick%24<12;rect(o.x+19,flap?o.y-12:o.y+13,7,16);rect(o.x+24,flap?o.y-18:o.y+23,5,9);rect(o.x+31,o.y+9,10,3)}
function label(text,x,y,size=14,align='left'){ctx.font=`bold ${size}px monospace`;ctx.textAlign=align;ctx.fillText(text,x,y)}
function draw(){ctx.clearRect(0,0,640,210);const night=Math.floor(score/700)%2===1;document.body.classList.toggle('night',night);ctx.fillStyle=night?'#acacac':'#535353';ctx.globalAlpha=.7;clouds.forEach(c=>{rect(c.x,c.y+8,43,1);rect(c.x+5,c.y+3,10,1);rect(c.x+15,c.y-3,13,1);rect(c.x+15,c.y-3,1,7);rect(c.x+28,c.y-2,1,6);rect(c.x+29,c.y+3,9,1);rect(c.x+38,c.y+4,1,4)});ctx.globalAlpha=1;rect(0,166,640,1);for(let i=0;i<25;i++){let x=((i*37-ground)%680+680)%680;rect(x,170+(i*7%11),i%3===0?7:3,1)}drawDino();obstacles.forEach(o=>o.type==='bird'?bird(o):cactus(o));ctx.globalAlpha=.65;label('HI '+String(Math.floor(best)).padStart(5,'0'),450,20);ctx.globalAlpha=1;label(String(Math.floor(score)).padStart(5,'0'),635,20,14,'right');if(state==='ready')label('¿LISTO PARA CORRER?',320,86,16,'center');if(state==='dead'){label('G A M E  O V E R',320,82,18,'center');ctx.strokeStyle=ctx.fillStyle;ctx.lineWidth=3;ctx.strokeRect(307,101,26,23);rect(313,111,13,3);rect(313,107,3,7);rect(324,111,3,8)}if(state==='paused')label('PAUSA',320,84,20,'center')}
function start(){state='running';score=0;speed=6;tick=0;ground=0;next=75;obstacles=[];dino.y=0;dino.vy=0;dino.duck=false;hint.textContent='Salta los cactus. Esquiva las aves.';statusEl.textContent='Partida iniciada';pauseButton.textContent='Ⅱ Pausa'}
function jump(){if(state==='dead'&&performance.now()-deadAt<350)return;if(state==='ready'||state==='dead')start();if(state==='running'&&dino.y===0){dino.duck=false;dino.vy=11.5}}
function pause(){if(state==='running'){state='paused';hint.textContent='Presiona P para continuar'}else if(state==='paused'){state='running';hint.textContent='Salta los cactus. Esquiva las aves.'}pauseButton.textContent=state==='paused'?'▶ Continuar':'Ⅱ Pausa';pauseButton.setAttribute('aria-label',state==='paused'?'Continuar partida':'Pausar partida')}
function die(){state='dead';deadAt=performance.now();best=Math.max(best,Math.floor(score));try{localStorage.setItem('dino-best',String(best))}catch{}hint.textContent='Presiona espacio o toca el juego para reintentar';statusEl.textContent=`Fin de la partida. ${Math.floor(score)} puntos.`}
function update(dt){tick+=dt;score+=dt*.15;speed=Math.min(13,6+score/180);ground+=speed*dt;clouds.forEach(c=>{c.x-=.3*dt;if(c.x< -50)c.x=670});if(dino.y>0||dino.vy>0){dino.y+=dino.vy*dt;dino.vy-=(dino.duck?1.3:.6)*dt;if(dino.y<0){dino.y=0;dino.vy=0}}next-=dt;if(next<=0){if(score>220&&Math.random()<.25){obstacles.push({type:'bird',x:670,y:[115,137,90][Math.floor(Math.random()*3)],w:40})}else{let count=1+Math.floor(Math.random()*(score>100?3:2));obstacles.push({type:'cactus',x:670,h:30+Math.floor(Math.random()*14),count,w:count*17})}next=(190+Math.random()*180+speed*30)/speed}obstacles.forEach(o=>o.x-=speed*dt);obstacles=obstacles.filter(o=>o.x> -70);const duck=dino.duck&&dino.y===0;const box={x:48,y:166-dino.y-(duck?22:35),w:duck?45:25,h:duck?20:33};for(const o of obstacles){const b=o.type==='bird'?{x:o.x+5,y:o.y+2,w:30,h:15}:{x:o.x+3,y:166-o.h+3,w:o.w-4,h:o.h-3};if(box.x<b.x+b.w&&box.x+box.w>b.x&&box.y<b.y+b.h&&box.y+box.h>b.y){die();break}}}
function frame(now){let dt=Math.min((now-last)/16.6667,2);last=now;if(state==='running')update(dt);draw();requestAnimationFrame(frame)}
addEventListener('keydown',e=>{if(['Space','ArrowUp','ArrowDown'].includes(e.code)){if(e.target.tagName==='BUTTON'&&e.code==='Space')return;e.preventDefault();if(e.code==='ArrowDown')dino.duck=true;else if(!e.repeat)jump()}if(e.code==='KeyP'&&!e.repeat)pause()});addEventListener('keyup',e=>{if(e.code==='ArrowDown')dino.duck=false;if(['Space','ArrowUp'].includes(e.code)&&dino.vy>5)dino.vy=5});addEventListener('blur',()=>{dino.duck=false;if(state==='running')pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden&&state==='running')pause()});canvas.addEventListener('pointerdown',e=>{e.preventDefault();jump()});pauseButton.onclick=pause;document.getElementById('jump').addEventListener('pointerdown',e=>{e.preventDefault();jump()});const duckButton=document.getElementById('duck');duckButton.addEventListener('pointerdown',e=>{e.preventDefault();duckButton.setPointerCapture(e.pointerId);dino.duck=true});['pointerup','pointercancel','lostpointercapture'].forEach(name=>duckButton.addEventListener(name,()=>dino.duck=false));requestAnimationFrame(frame);
